DO $$
DECLARE
  rec RECORD;
  cur_status INT;
  cur_editor INT;
BEGIN
  FOR rec IN SELECT * FROM moderation_events ORDER BY event_id LOOP
    SELECT status, editor_id INTO cur_status, cur_editor FROM articles WHERE article_id = rec.article_id;
    IF rec.event_type = 1 AND cur_status = 0 THEN
      UPDATE articles SET status = 1 WHERE article_id = rec.article_id;
    ELSIF rec.event_type = 2 AND cur_status = 1 THEN
      UPDATE articles SET status = 2, editor_id = rec.editor_id WHERE article_id = rec.article_id;
    ELSIF rec.event_type = 3 AND cur_status = 1 THEN
      UPDATE articles SET status = 3, editor_id = rec.editor_id WHERE article_id = rec.article_id;
    ELSIF rec.event_type = 4 AND (cur_status = 1 OR cur_status = 2) THEN
      UPDATE articles SET status = 0, editor_id = NULL WHERE article_id = rec.article_id;
    END IF;
  END LOOP;
END $$;

SELECT * FROM articles ORDER BY article_id;
